const KEY='folio.profile.v1';
const initial={name:'Billy Otieno',slug:'billy-otieno',role:'Computer science student · Nairobi, Kenya',bio:'I’m a curious computer science student who enjoys building thoughtful digital products. I care about clean interfaces, useful tools, and the little details that make software feel good to use.',email:'billy@example.com',location:'Nairobi, Kenya',school:'University of Nairobi',degree:'BSc Computer Science',gradYear:'2027',experience:'',phone:'',profileImage:'',behance:'',traits:[],cvEducation:[],languages:[],expertise:[],achievements:[],references:[],fatherName:'',dateOfBirth:'',gender:'',maritalStatus:'',skills:['JavaScript','React','Python','Figma','Node.js','PostgreSQL'],github:'billyotieno',linkedin:'',website:'',template:'minimal',accent:'#6f895d',font:'Manrope',projects:[{title:'Campus Connect',description:'A campus events platform that helps students discover what’s happening around them.',stack:['React','Node.js','PostgreSQL'],github:'https://github.com/billyotieno/campus-connect',live:'',image:''},{title:'GreenRoute',description:'A route planner that finds greener ways to move around the city.',stack:['Python','Flask','OpenStreetMap'],github:'https://github.com/billyotieno/greenroute',live:'',image:''}],views:0,visits:[]};
let data=load();const apiEnabled=location.protocol==='http:'||location.protocol==='https:';let authenticated=false,authMode='signup',booting=apiEnabled,serverError='',publicSlug='',loadedPublicSlug='',analyticsRemote=null;let route=location.hash.startsWith('#/p/')||(apiEnabled&&location.pathname.split('/').filter(Boolean).length&&!location.pathname.endsWith('/index.html'))?'public':'dashboard';let toastTimer;
function load(){try{return {...initial,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return structuredClone(initial)}}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}
async function api(path,options={}){const response=await fetch(path,{...options,credentials:'same-origin',headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});if(response.status===204)return null;const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||`Request failed (${response.status}).`);return body}
async function hydrate(){if(!apiEnabled)return;try{const {user}=await api('/api/auth/me');authenticated=!!user;if(authenticated){const result=await api('/api/portfolio');if(result.portfolio){data={...initial,...result.portfolio};save()}analyticsRemote=await api('/api/analytics');data.views=analyticsRemote.total}if(route==='public')loadPublic();}catch(e){serverError='Could not reach the folio server. Start it with npm start and make sure MongoDB is running.'}finally{booting=false;render()}}
async function loadPublic(){const fromHash=location.hash.startsWith('#/p/')?location.hash.slice(4):'';const fromPath=location.pathname.split('/').filter(Boolean)[0]||'';publicSlug=decodeURIComponent(fromHash||fromPath||data.slug);if(loadedPublicSlug===publicSlug)return;loadedPublicSlug=publicSlug;publicLoadError='';try{const result=await api(`/api/public/${encodeURIComponent(publicSlug)}`);data={...initial,...result.portfolio};save();render()}catch(e){publicLoadError=e.message;render()}}
let publicLoadError='';
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function parseList(value,separator=','){return value.split(separator).map(item=>item.trim()).filter(Boolean)}
function readProfileForm(values){for(const key of ['name','role','bio','email','location','school','degree','gradYear','experience','phone','profileImage','behance','fatherName','dateOfBirth','gender','maritalStatus','github','linkedin','website'])data[key]=(values[key]||'').trim();data.slug=values.slug.trim().toLowerCase().replace(/[^a-z0-9-]/g,'-');data.skills=parseList(values.skills);data.traits=parseList(values.traits);data.expertise=parseList(values.expertise);data.cvEducation=parseList(values.cvEducation,'\n');data.languages=parseList(values.languages,'\n');data.achievements=parseList(values.achievements,'\n');data.references=parseList(values.references,'\n')}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
const icon={home:'⌂',profile:'◉',projects:'▧',design:'◈',analytics:'▥'};
function navItem(key,label){return `<button type="button" data-route="${key}" aria-label="${label}" class="${route===key?'active':''}"><span class="nav-icon" aria-hidden="true">${icon[key]}</span><span class="nav-label">${label}</span></button>`}
function shell(content){return `<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">f</span> folio</div><div class="workspace-label">Workspace</div><nav class="nav">${navItem('dashboard','Overview')}${navItem('profile','My profile')}${navItem('projects','Projects')}${navItem('design','Design studio')}${navItem('analytics','Analytics')}</nav><div class="side-bottom"><div class="plan-card"><strong>Your portfolio is live ✨</strong><p>Keep your story fresh. Add your latest work and share your link.</p><div class="plan-meter"><span></span></div></div><div class="user-chip"><div class="avatar">${esc((data.name||'B')[0])}</div><div><strong>${esc(data.name)}</strong><small>Free workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">My workspace <span> / </span> <b>${pageLabel()}</b></div><div class="top-actions">${apiEnabled&&authenticated?'<button class="icon-btn" data-action="logout">↪ &nbsp; Sign out</button>':''}<button class="icon-btn" data-action="share">↗ &nbsp; Share</button><button class="btn btn-primary" data-action="preview">◉ &nbsp; View portfolio</button></div></header><div class="content">${content}</div></main></div>`}
function pageLabel(){return ({dashboard:'Overview',profile:'My profile',projects:'Projects','design':'Design studio','analytics':'Analytics'})[route]||'Overview'}
function heading(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function dashboard(){const dayViews=analyticsRemote?analyticsRemote.last24:data.visits.filter(x=>Date.now()-x<86400000).length;const dateLabel=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();return `${heading(dateLabel,`Good morning, ${esc(data.name.split(' ')[0])} 👋`,'Your portfolio is taking shape. Here’s how things are looking.')}
<section class="welcome"><div class="welcome-content"><div class="eyebrow">YOUR PORTFOLIO IS PUBLISHED</div><h2>Make your next move memorable.</h2><p>Your story deserves a home. Keep building it, one project at a time.</p></div><button class="btn btn-green" data-action="preview">See your portfolio ↗</button></section>
<section class="stats"><div class="stat"><div class="stat-top">Portfolio views <span class="stat-icon">◉</span></div><div class="stat-value">${data.views}</div><div class="stat-sub">${dayViews} in the last 24 hours</div></div><div class="stat"><div class="stat-top">Projects <span class="stat-icon">▧</span></div><div class="stat-value">${data.projects.length.toString().padStart(2,'0')}</div><div class="stat-sub">Show your best work</div></div><div class="stat"><div class="stat-top">Profile strength <span class="stat-icon">✦</span></div><div class="stat-value">${profileScore()}%</div><div class="stat-sub">${profileScore()>=80?'Looking sharp':'A few details will make it shine'}</div></div></section>
<div class="grid-2"><section class="card"><div class="card-head"><h3>Your public portfolio</h3><a href="#/p/${esc(data.slug)}" class="subtle-link" data-action="preview">Open portfolio ↗</a></div><div class="portfolio-row"><div class="portfolio-thumb">${esc(data.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong>${esc(data.name)} — Portfolio</strong><small>folio.site/${esc(data.slug)}</small></div><span class="status-pill row-end">● &nbsp; Live</span></div><div class="activity"><div class="activity-item"><span class="activity-dot"></span>Your portfolio is published<time>Just now</time></div><div class="activity-item"><span class="activity-dot"></span>${data.projects.length} projects on display<time>Today</time></div><div class="activity-item"><span class="activity-dot"></span>${esc(data.template)} template selected<time>Today</time></div></div></section><section class="card"><div class="card-head"><h3>Quick setup</h3><span class="status-pill">${profileScore()}% complete</span></div><div class="activity checklist">${[['Add your profile photo',false],['Write a short introduction',!!data.bio],['Add at least 3 projects',data.projects.length>=3],['Connect your GitHub',!!data.github]].map(([x,ok])=>`<div class="check-item ${ok?'':'pending'}"><span class="check-circle">${ok?'✓':'·'}</span>${x}</div>`).join('')}<button class="subtle-link" data-route="profile" style="justify-self:start;margin-top:5px">Complete your profile →</button></div></section></div>`}
function profileBase(){return `${heading('YOUR STORY','My profile','The details that make your portfolio yours.',`<button class="btn" data-action="export">↓ &nbsp; Export ZIP</button>`)}<div class="form-layout"><form id="profile-form"><section class="form-card"><h3>Personal details</h3><p>Start with the basics. You can always change these later.</p><div class="fields"><div class="field"><label>Full name</label><input name="name" value="${esc(data.name)}" placeholder="Your name" required></div><div class="field"><label>Professional title</label><input name="role" value="${esc(data.role)}" placeholder="Designer, developer, student..."></div><div class="field full"><label>About you</label><textarea name="bio" placeholder="A little about what you do and what you care about...">${esc(data.bio)}</textarea><small>A few genuine sentences help visitors understand your work.</small></div><div class="field"><label>Location</label><input name="location" value="${esc(data.location)}" placeholder="City, country"></div><div class="field"><label>Contact email</label><input name="email" type="email" value="${esc(data.email)}" placeholder="you@example.com"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(data.phone)}" placeholder="+92 ..."></div><div class="field"><label>Profile photo URL</label><input name="profileImage" type="url" value="${esc(data.profileImage)}" placeholder="https://..."></div></div></section><section class="form-card"><h3>Education & experience</h3><p>Share what you’re learning and where you’ve put it to work.</p><div class="fields"><div class="field"><label>School</label><input name="school" value="${esc(data.school)}"></div><div class="field"><label>Degree or program</label><input name="degree" value="${esc(data.degree)}"></div><div class="field"><label>Expected graduation</label><input name="gradYear" value="${esc(data.gradYear)}"></div><div class="field full"><label>Additional education</label><textarea name="cvEducation" placeholder="One credential per line, e.g. F.Sc Pre-Medical — 2022">${esc((data.cvEducation||[]).join('\n'))}</textarea></div><div class="field full"><label>Experience</label><textarea name="experience" placeholder="One role per paragraph: role, organization, dates, and what you worked on">${esc(data.experience||'')}</textarea></div></div></section><section class="form-card"><h3>Links & skills</h3><p>Help people find you and see what you know.</p><div class="fields"><div class="field"><label>GitHub username</label><input name="github" value="${esc(data.github)}" placeholder="username"></div><div class="field"><label>LinkedIn URL</label><input name="linkedin" value="${esc(data.linkedin)}" placeholder="https://linkedin.com/in/..."></div><div class="field"><label>Behance URL</label><input name="behance" value="${esc(data.behance)}" placeholder="https://behance.net/..."></div><div class="field"><label>Personal website</label><input name="website" value="${esc(data.website)}" placeholder="https://..."></div><div class="field"><label>Portfolio URL slug</label><input name="slug" value="${esc(data.slug)}" pattern="[a-zA-Z0-9-]+" required><small>folio.site/<span id="slug-preview">${esc(data.slug)}</span></small></div><div class="field full"><label>Skills</label><input name="skills" value="${esc(data.skills.join(', '))}" placeholder="Photoshop, Illustrator, Canva"><small>Separate skills with commas.</small></div></div></section><section class="form-card"><h3>CV details</h3><p>Optional sections for the new CV layouts. Only completed details appear publicly.</p><div class="fields"><div class="field full"><label>Profile tags</label><input name="traits" value="${esc((data.traits||[]).join(', '))}" placeholder="Creative, Detail-Oriented, Dedicated"></div><div class="field full"><label>Expertise</label><input name="expertise" value="${esc((data.expertise||[]).join(', '))}" placeholder="Poster design, Logo & branding"></div><div class="field full"><label>Languages</label><textarea name="languages" placeholder="One per line, e.g. Urdu · Native">${esc((data.languages||[]).join('\n'))}</textarea></div><div class="field full"><label>Achievements & certificates</label><textarea name="achievements" placeholder="One per line">${esc((data.achievements||[]).join('\n'))}</textarea></div><div class="field"><label>Father’s name</label><input name="fatherName" value="${esc(data.fatherName)}"></div><div class="field"><label>Date of birth</label><input name="dateOfBirth" value="${esc(data.dateOfBirth)}" placeholder="DD Month YYYY"></div><div class="field"><label>Gender</label><input name="gender" value="${esc(data.gender)}"></div><div class="field"><label>Marital status</label><input name="maritalStatus" value="${esc(data.maritalStatus)}"></div></div></section><div class="form-actions"><button class="btn btn-primary" type="submit">Save changes</button></div></form><aside><div class="hint-card"><h4>💡 Make it sound like you</h4><p>A good bio tells people what you’re interested in, what you’re learning, and the kinds of problems you like to solve. Keep it conversational.</p></div></aside></div>`}
function profile(){return profileBase().replace('</form>',`${cvReferencesEditor()}</form>`)}
function cvReferencesEditor(){return `<section class="form-card"><h3>CV references</h3><p>One reference per line. Include their name, title, and contact details.</p><div class="field"><label>References</label><textarea name="references" placeholder="Name · Job title · Phone · Email">${esc((data.references||[]).join('\n'))}</textarea></div></section>`}
function projects(){return `${heading('YOUR WORK','Projects','A few good projects tell a better story than a long list.',`<button class="btn" data-action="github-import">⌘ &nbsp; Import from GitHub</button><button class="btn btn-primary" data-action="add-project">＋ &nbsp; Add project</button>`)}<div class="project-list">${data.projects.length?data.projects.map((p,i)=>`<section class="card project-card"><div class="project-icon">${['◒','▧','⌘','✳'][i%4]}</div><div class="project-copy"><strong>${esc(p.title)}</strong><p>${esc(p.description)}</p><div class="tags">${(p.stack||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div><div class="project-actions"><button class="mini-btn" title="Edit" data-action="edit-project" data-index="${i}">✎</button><button class="mini-btn" title="Delete" data-action="delete-project" data-index="${i}">×</button></div></section>`).join(''):`<section class="card empty"><strong>No projects yet</strong>Add a project or import one from GitHub to get started.</section>`}</div>`}
const templates=[['minimal','Minimal','Quiet, clear, considered'],['editorial','Editorial','A little more personality'],['studio','Studio','Bold color, big ideas'],['cv-clean','CV Clean','White page and green accents'],['cv-sidebar','CV Sidebar','Navy sidebar and profile'],['cv-header','CV Classic','Dark header and two columns'],['cv-orange','CV Orange','Curved orange accents and dark sidebar']];
function design(){return `${heading('MAKE IT YOURS','Design studio','Choose a look that feels like you. Changes preview instantly.',`<button class="btn" data-action="preview">↗ &nbsp; Open full preview</button>`)}<div class="form-layout"><div><section class="form-card"><h3>Pick a starting point</h3><p>Your content stays the same. Choose a layout that suits it.</p><div class="template-grid">${templates.map(([id,n,d],i)=>`<button class="template-card ${data.template===id?'selected':''}" data-template="${id}"><div class="template-preview template-preview-${id}"><div class="preview-paper"><div class="preview-line short"></div><div class="preview-line long"></div><div class="preview-line"></div><div class="preview-blocks"><div class="preview-block"></div><div class="preview-block"></div></div></div></div><strong>${n}</strong><small>${d}</small></button>`).join('')}</div></section><section class="form-card"><h3>Color & typography</h3><p>A small personal touch goes a long way.</p><div class="look-editor">${['#6f895d','#547ba2','#c27b51','#a66b85','#323634'].map(c=>`<button class="swatch ${data.accent===c?'selected':''}" style="background:${c}" data-color="${c}" aria-label="Choose ${c}"></button>`).join('')}<input type="color" class="swatch-input" data-color-input value="${esc(data.accent)}" aria-label="Custom accent color"><select data-font><option ${data.font==='Manrope'?'selected':''}>Manrope</option><option ${data.font==='DM Sans'?'selected':''}>DM Sans</option><option ${data.font==='Georgia'?'selected':''}>Georgia</option></select></div></section></div><div class="preview-stage"><div class="eyebrow" style="margin:0 0 12px 3px">LIVE PREVIEW</div><div class="preview-frame">${miniSite()}</div></div></div>`}
function miniSite(){if(data.template.startsWith('cv-'))return `<div class="mini-cv mini-cv-${esc(data.template)}"><div class="mini-cv-head"><span></span><i></i><i></i></div><div class="mini-cv-body"><aside><i></i><i></i><i></i><i></i></aside><section><i></i><i></i><i></i><i></i><i></i><i></i></section></div></div>`;return `<div class="mini-site theme-${esc(data.template)}" style="--accent:${esc(data.accent)};--portfolio-font:${esc(data.font)}"><div class="mini-nav"><b>${esc(data.name)}</b><span>WORK &nbsp;&nbsp; ABOUT &nbsp;&nbsp; CONTACT</span></div><div class="mini-hero"><div class="eyebrow">${esc(data.role)}</div><h2>Hi, I’m ${esc(data.name.split(' ')[0])}.</h2><p>${esc(data.bio)}</p></div><h4>Selected work</h4><div class="mini-projects">${data.projects.slice(0,2).map(p=>`<div class="mini-project">${esc(p.title)}<small>${esc((p.stack||[]).slice(0,3).join(' · '))}</small></div>`).join('')}</div></div>`}
function analytics(){const now=Date.now(),days=Array.from({length:7},(_,i)=>{const d=new Date(now-(6-i)*86400000);const day=(analyticsRemote?.days||[]).find(x=>String(x.day).slice(0,10)===d.toISOString().slice(0,10));return{label:d.toLocaleDateString('en',{weekday:'short'}),count:analyticsRemote?(day?.count||0):data.visits.filter(x=>new Date(x).toDateString()===d.toDateString()).length}});const max=Math.max(1,...days.map(x=>x.count));return `${heading('GROWING YOUR AUDIENCE','Analytics','A simple view of how people are finding your work.') }<div class="stats"><div class="stat"><div class="stat-top">All-time views <span class="stat-icon">◉</span></div><div class="stat-value">${analyticsRemote?.total??data.views}</div><div class="stat-sub">Since you published</div></div><div class="stat"><div class="stat-top">Last 7 days <span class="stat-icon">⌁</span></div><div class="stat-value">${analyticsRemote?.last7??days.reduce((a,b)=>a+b.count,0)}</div><div class="stat-sub">Portfolio visits</div></div><div class="stat"><div class="stat-top">Projects <span class="stat-icon">▧</span></div><div class="stat-value">${data.projects.length.toString().padStart(2,'0')}</div><div class="stat-sub">Currently featured</div></div></div><section class="card"><div class="card-head"><h3>Portfolio views</h3><span class="eyebrow">LAST 7 DAYS</span></div><div class="bar-chart">${days.map((d,i)=>`<div class="bar-col"><div class="bar ${i===6?'today':''}" style="height:${Math.max(4,d.count/max*100)}%"></div><small>${d.label}</small></div>`).join('')}</div></section><div class="notice" style="margin-top:14px">${apiEnabled?'Views are recorded on the server whenever your public portfolio is opened.':'Views are counted locally in this browser.'}</div>`}
function cvUrl(value){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?esc(url.href):''}catch{return''}}
function cvSection(title,content){return content?`<section class="cv-section"><h2>${title}</h2>${content}</section>`:''}
function cvList(items,style='list'){return items.length?`<ul class="cv-${style}">${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}
function cvPage(){
  const sidebarTemplate=data.template==='cv-sidebar';
  const photo=cvUrl(data.profileImage);
  const avatar=photo?`<img src="${photo}" alt="">`:`<span>${esc(data.name.split(/\s+/).map(part=>part[0]).slice(0,2).join(''))}</span>`;
  const contact=[
    data.phone?`<a href="tel:${encodeURIComponent(data.phone)}">${esc(data.phone)}</a>`:'',
    data.email?`<a href="mailto:${encodeURIComponent(data.email)}">${esc(data.email)}</a>`:'',
    data.location?`<span>${esc(data.location)}</span>`:'',
    data.github?`<a href="https://github.com/${encodeURIComponent(data.github)}" target="_blank" rel="noreferrer">GitHub</a>`:'',
    ...[['LinkedIn',data.linkedin],['Behance',data.behance],['Website',data.website]].map(([label,value])=>{const url=cvUrl(value);return url?`<a href="${url}" target="_blank" rel="noreferrer">${label}</a>`:''})
  ].filter(Boolean);
  const education=data.cvEducation?.length?data.cvEducation:[data.degree||data.school?`${data.degree}${data.school?` · ${data.school}`:''}${data.gradYear?` · ${data.gradYear}`:''}`:''].filter(Boolean);
  const experience=(data.experience||'').split(/\n+/).map(item=>item.trim()).filter(Boolean);
  const personal=[['Father’s Name',data.fatherName],['Date of Birth',data.dateOfBirth],['Gender',data.gender],['Marital Status',data.maritalStatus]].filter(([,value])=>value);
  const sidebar=`${sidebarTemplate?`<div class="cv-avatar">${avatar}</div><h1>${esc(data.name)}</h1><p class="cv-role">${esc(data.role)}</p>${cvList(data.traits||[],'tags')}`:''}${cvSection('Contact',contact.length?`<ul class="cv-contact">${contact.map(item=>`<li>${item}</li>`).join('')}</ul>`:'')}${cvSection('Education',cvList(education))}${cvSection('Skills',cvList(data.skills||[]))}${cvSection('Languages',cvList(data.languages||[]))}`;
  const banner=sidebarTemplate?'':`<header class="cv-header"><div class="cv-avatar">${avatar}</div><div><h1>${esc(data.name)}</h1><p class="cv-role">${esc(data.role)}</p>${cvList(data.traits||[],'tags')}</div></header>`;
  const main=`${cvSection('Professional Summary',data.bio?`<p>${esc(data.bio)}</p>`:'')}${cvSection('Experience',cvList(experience,'experience'))}${cvSection('Expertise',cvList(data.expertise?.length?data.expertise:(data.skills||[]),'tags'))}${cvSection('Achievements',cvList(data.achievements||[]))}${personal.length?cvSection('Personal Details',`<dl class="cv-personal">${personal.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`):''}`;
  return `<main class="cv-page ${sidebarTemplate?'cv-sidebar':'cv-header-layout'}"><div class="cv-layout">${banner}<aside class="cv-sidebar-column">${sidebar}</aside><div class="cv-main-column">${main}<footer class="cv-footer">${esc(data.name)}${data.location?` · ${esc(data.location)}`:''}</footer></div></div><button class="btn cv-print" data-action="print">Print / Save as PDF</button><button class="icon-btn cv-back" data-action="back">← Back to editor</button></main>`;
}
function cvCleanPage(){
  const contact=[
    data.email?`<a href="mailto:${encodeURIComponent(data.email)}">${esc(data.email)}</a>`:'',
    data.phone?`<a href="tel:${encodeURIComponent(data.phone)}">${esc(data.phone)}</a>`:'',
    data.location?`<span>${esc(data.location)}</span>`:'',
    ...[['LinkedIn',data.linkedin],['Website',data.website]].map(([label,value])=>{const url=cvUrl(value);return url?`<a href="${url}" target="_blank" rel="noreferrer">${label}</a>`:''})
  ].filter(Boolean);
  const education=data.cvEducation?.length?data.cvEducation:[data.degree||data.school?`${data.degree}${data.school?` · ${data.school}`:''}${data.gradYear?` · ${data.gradYear}`:''}`:''].filter(Boolean);
  const experience=(data.experience||'').split(/\n+/).map(item=>item.trim()).filter(Boolean);
  const sidebar=`${cvSection('Skills',cvList(data.skills||[]))}${cvSection('Certifications',cvList(data.achievements||[]))}${cvSection('Languages',cvList(data.languages||[]))}${cvSection('References',cvList(data.references||[],'references'))}`;
  const main=`${cvSection('Professional Summary',data.bio?`<p>${esc(data.bio)}</p>`:'')}${cvSection('Experience',cvList(experience,'experience'))}${cvSection('Education',cvList(education))}${cvSection('Expertise',cvList(data.expertise||[],'tags'))}`;
  return `<main class="cv-page cv-clean"><div class="cv-layout cv-clean-sheet"><header class="cv-clean-header"><h1>${esc(data.name)}</h1><p class="cv-role">${esc(data.role)}</p>${contact.length?`<div class="cv-clean-contact">${contact.join('<span aria-hidden="true">|</span>')}</div>`:''}</header><div class="cv-clean-columns"><aside class="cv-clean-sidebar">${sidebar}</aside><div class="cv-clean-main">${main}</div></div></div><button class="btn cv-print" data-action="print">Print / Save as PDF</button><button class="icon-btn cv-back" data-action="back">← Back to editor</button></main>`;
}
function cvOrangePage(){
  const education=data.cvEducation?.length?data.cvEducation:[data.degree||data.school?`${data.degree}${data.school?` · ${data.school}`:''}${data.gradYear?` · ${data.gradYear}`:''}`:''].filter(Boolean);
  const website=cvUrl(data.website);
  const contact=[
    data.phone?`<a href="tel:${encodeURIComponent(data.phone)}">${esc(data.phone)}</a>`:'',
    data.email?`<a href="mailto:${encodeURIComponent(data.email)}">${esc(data.email)}</a>`:'',
    data.location?`<span>${esc(data.location)}</span>`:'',
    website?`<a href="${website}">${esc(data.website.replace(/^https?:\/\//,''))}</a>`:'',
    ...[['LinkedIn',data.linkedin],['Behance',data.behance]].map(([label,value])=>{const url=cvUrl(value);return url?`<a href="${url}" target="_blank" rel="noreferrer">${label}</a>`:''})
  ].filter(Boolean);
  const experience=(data.experience||'').split(/\n+/).map(item=>item.trim()).filter(Boolean);
  const photo=cvUrl(data.profileImage);
  const avatar=photo?`<img src="${photo}" alt="${esc(data.name)}">`:`<span>${esc(data.name.split(/\s+/).map(part=>part[0]).slice(0,2).join(''))}</span>`;
  const references=data.references||[];
  return `<main class="cv-page cv-orange"><div class="cv-orange-sheet"><svg class="cv-orange-ribbons" viewBox="0 0 794 1123" preserveAspectRatio="none" aria-hidden="true"><path fill="#f79538" d="M225 0h569v235C735 171 687 120 609 83 495 28 354 20 225 0Z"/><path fill="#130702" d="M363 0h431v119C701 70 646 40 579 22 498 0 423 0 363 0Z"/><path fill="#c85b31" d="M520 0h274v86C720 54 677 36 632 22 589 9 554 3 520 0Z"/><path fill="#f79538" d="M0 1013c134 92 268 110 409 94 155-18 280-80 385-151v167H0Z"/><path fill="#c85b31" d="M0 1059c146 84 273 87 416 59 147-29 270-94 378-162v99c-119 75-241 124-384 153-156 31-284 18-410-44Z"/><path fill="#130702" d="M0 1013c126 87 259 108 404 94 149-14 283-72 390-145v54c-111 72-237 119-378 142-156 25-287 4-416-74Z"/></svg><div class="cv-orange-columns"><section class="cv-orange-main"><header class="cv-orange-title"><h1>${esc(data.name)}</h1><p>${esc(data.role)}</p></header>${cvSection('About Me',data.bio?`<p>${esc(data.bio)}</p>`:'')}${cvSection('Experience',cvList(experience,'experience'))}${cvSection('Reference',cvList(references,'references'))}</section><aside class="cv-orange-side"><div class="cv-orange-photo">${avatar}</div>${cvSection('Education',cvList(education,'orange-list'))}${cvSection('Skills',cvList(data.skills||[],'orange-list'))}${cvSection('Language',cvList(data.languages||[],'orange-list'))}${cvSection('Contact',contact.length?`<ul class="cv-contact cv-orange-contact">${contact.map(item=>`<li>${item}</li>`).join('')}</ul>`:'')}</aside></div><button class="btn cv-print" data-action="print">Print / Save as PDF</button><button class="icon-btn cv-back" data-action="back">← Back to editor</button></div></main>`;
}
function publicPage(){const visits=data.visits;const last=visits[visits.length-1];if(!last||Date.now()-last>30000){data.views++;data.visits.push(Date.now());data.visits=data.visits.slice(-300);save()}if(data.template==='cv-orange')return cvOrangePage();if(data.template==='cv-clean')return cvCleanPage();if(data.template.startsWith('cv-'))return cvPage();const name=esc(data.name);return `<div class="public-page theme-${esc(data.template)}" style="--accent:${esc(data.accent)}"><nav class="public-nav"><a class="brand-name" href="#/p/${esc(data.slug)}">${name}</a><div><a href="#work">Work</a> &nbsp;&nbsp; <a href="#about">About</a> &nbsp;&nbsp; <a href="#contact">Contact</a></div><button class="btn" data-action="print">↓ &nbsp; Download CV</button></nav><section class="public-hero"><div class="eyebrow">${esc(data.role)}${data.location?' · '+esc(data.location):''}</div><h1>Hi, I’m ${esc(data.name.split(' ')[0])}.<br>I build things for the web.</h1><p>${esc(data.bio)}</p><p style="font-size:12px;margin-top:20px">${data.email?`<a style="color:var(--accent);font-weight:700;text-decoration:none" href="mailto:${esc(data.email)}">Let’s work together ↗</a>`:''}</p></section><section class="public-section" id="work"><h2>A few things I’ve made.</h2><div class="public-projects">${data.projects.map(p=>`<article class="public-project"><div class="public-project-visual">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.title)}" style="width:100%;height:100%;object-fit:cover">`:'✳'}</div><div class="public-project-body"><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="tags" style="margin-bottom:13px">${(p.stack||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="public-links">${p.live?`<a href="${esc(p.live)}" target="_blank" rel="noreferrer">Live project ↗</a>`:''}${p.github?`<a href="${esc(p.github)}" target="_blank" rel="noreferrer">GitHub ↗</a>`:''}</div></div></article>`).join('')||'<p class="eyebrow">Projects are on their way.</p>'}</div></section><section class="public-section" id="about"><div class="public-about"><div><div class="eyebrow">A LITTLE ABOUT ME</div><h2 style="margin-top:10px">Always learning,<br>always building.</h2><p style="font-size:12px;line-height:1.8;color:#7d877d">${esc(data.bio)}</p>${data.school?`<p style="font-size:11px;color:#6f7a70">${esc(data.degree)} · ${esc(data.school)}${data.gradYear?' · '+esc(data.gradYear):''}</p>`:''}</div><div><h2>Things I work with.</h2><div class="skill-list">${data.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div></div></section><section class="public-section" id="contact"><div class="contact-box"><h3>Have something in mind?</h3><p>I’d love to hear about it. Drop me a note and I’ll get back to you.</p><a class="btn btn-primary" href="mailto:${esc(data.email)}?subject=${encodeURIComponent('Hello from your portfolio')}">Say hello ↗</a></div></section><footer class="public-footer">Designed with folio · ${name}</footer><button class="icon-btn" style="position:fixed;bottom:16px;right:16px" data-action="back">← Back to editor</button></div>`}
function portfolioSocialHTML(){const href=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?esc(u.href):''}catch{return''}};const links=[];if(data.github)links.push(`<a href="https://github.com/${encodeURIComponent(data.github)}" target="_blank" rel="noreferrer">GitHub ↗</a>`);const linkedin=href(data.linkedin),website=href(data.website);if(linkedin)links.push(`<a href="${linkedin}" target="_blank" rel="noreferrer">LinkedIn ↗</a>`);if(website)links.push(`<a href="${website}" target="_blank" rel="noreferrer">Website ↗</a>`);return links.length?` &nbsp; ${links.join(' &nbsp; ')}`:''}
function authPage(){return `<main class="auth-page"><section class="auth-card"><div class="brand"><span class="brand-mark">f</span> folio</div><div class="eyebrow">YOUR WORK, BEAUTIFULLY TOLD</div><h1>${authMode==='signup'?'Make room for your work.':'Welcome back.'}</h1><p>${authMode==='signup'?'Create an account and start building a portfolio that feels like you.':'Sign in to keep shaping your portfolio.'}</p>${serverError?`<div class="notice">${esc(serverError)}</div>`:''}<form id="auth-form">${authMode==='signup'?'<div class="field"><label>Your name</label><input name="name" autocomplete="name" placeholder="Your name" required></div>':''}<div class="field"><label>Email address</label><input name="email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="10" autocomplete="${authMode==='signup'?'new-password':'current-password'}" placeholder="${authMode==='signup'?'At least 10 characters':'Your password'}" required></div><button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:5px" type="submit">${authMode==='signup'?'Create account':'Sign in'} →</button></form><div class="auth-switch">${authMode==='signup'?'Already have an account?':'New to folio?'} <button data-action="auth-toggle">${authMode==='signup'?'Sign in':'Create an account'}</button></div></section><div class="auth-footer">A little space for the work you’re proud of.</div></main>`}
function render(){if(location.hash.startsWith('#/p/'))route='public';if(booting){document.getElementById('app').innerHTML='<div class="loading-page">Loading folio…</div>';return}if(apiEnabled&&route==='public'&&loadedPublicSlug!==decodeURIComponent(location.hash.startsWith('#/p/')?location.hash.slice(4):location.pathname.split('/').filter(Boolean)[0]||data.slug)){document.getElementById('app').innerHTML='<div class="loading-page">Opening portfolio…</div>';loadPublic();return}if(apiEnabled&&!authenticated&&route!=='public'){document.getElementById('app').innerHTML=authPage();return}if(route==='public'){const host=document.getElementById('app');host.innerHTML=publicLoadError?`<div class="loading-page">${esc(publicLoadError)}<br><a href="/">Back to folio</a></div>`:publicPage();host.querySelector('.public-nav>div')?.insertAdjacentHTML('beforeend',portfolioSocialHTML());return}document.getElementById('app').innerHTML=shell(({dashboard,profile,projects,design,analytics})[route]());}
function modal(html){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`)}
function contactModal(){modal(`<div class="modal-head"><h2>Send ${esc(data.name.split(' ')[0])} a note</h2><button data-action="close-modal">×</button></div><p>Your message will go straight to the email listed on this portfolio.</p><form id="contact-form"><div class="field"><label>Your email</label><input type="email" name="email" required placeholder="you@example.com"></div><div class="field"><label>Your message</label><textarea name="message" required minlength="5" placeholder="What would you like to talk about?"></textarea></div><div class="form-actions"><button class="btn btn-primary" type="submit">Send message ↗</button></div></form>`)}
document.addEventListener('click',e=>{if(e.target.closest('[data-route="analytics"]')&&apiEnabled&&authenticated)api('/api/analytics').then(x=>{analyticsRemote=x;data.views=x.total;render()}).catch(err=>toast(err.message))},true);
document.addEventListener('click',e=>{const mail=e.target.closest('a[href^="mailto:"]');if(apiEnabled&&mail){e.preventDefault();contactModal()}});
function projectForm(index){const p=index==null?{title:'',description:'',stack:[],github:'',live:'',image:''}:data.projects[index];modal(`<div class="modal-head"><h2>${index==null?'Add a project':'Edit project'}</h2><button data-action="close-modal">×</button></div><p>Give visitors a quick look at what you made and how you made it.</p><form id="project-form" data-index="${index??''}"><div class="field"><label>Project title</label><input name="title" required value="${esc(p.title)}" placeholder="e.g. Campus Connect"></div><div class="field"><label>Description</label><textarea name="description" required placeholder="What does it do?">${esc(p.description)}</textarea></div><div class="fields"><div class="field"><label>Tech stack</label><input name="stack" value="${esc((p.stack||[]).join(', '))}" placeholder="React, Node.js"></div><div class="field"><label>GitHub URL</label><input name="github" type="url" value="${esc(p.github)}" placeholder="https://github.com/..."></div><div class="field"><label>Live project URL</label><input name="live" type="url" value="${esc(p.live)}" placeholder="https://..."></div><div class="field full"><label>Screenshot image URL</label><input name="image" type="url" value="${esc(p.image)}" placeholder="https://example.com/screenshot.png"></div></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">Save project</button></div></form>`)}
function githubModal(){modal(`<div class="modal-head"><h2>Import from GitHub</h2><button data-action="close-modal">×</button></div><p>Enter a public GitHub username. We’ll find your repositories and let you choose which ones to add.</p><form id="github-form"><div class="field"><label>GitHub username</label><input name="username" value="${esc(data.github)}" required placeholder="octocat"></div><div id="repo-results" class="repo-results" style="display:none"></div><div class="form-actions"><button class="btn btn-primary" type="submit" id="repo-submit">Find repositories ↗</button></div></form>`)}
function download(name,content,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportZip(){const page=portfolioHTML();const css=`body{font:16px Arial,sans-serif;color:#263126;margin:0}header,section,footer{max-width:920px;margin:0 auto;padding:35px 24px}header{display:flex;justify-content:space-between;border-bottom:1px solid #eee}h1{font-size:56px;letter-spacing:-2px}p{color:#707970;line-height:1.7}.projects{display:grid;grid-template-columns:1fr 1fr;gap:16px}.project{background:#f3f5f1;padding:20px;border-radius:8px}a{color:${data.accent}}@media(max-width:600px){.projects{grid-template-columns:1fr}h1{font-size:40px}}`;const html=page.replace('</head>',`<link rel="stylesheet" href="styles.css"></head>`);download(`${data.slug}-portfolio.zip`,zipStore({'index.html':html,'styles.css':css,'README.txt':'Your portfolio is ready to host. Upload these files to GitHub Pages or Netlify.'}),'application/zip');toast('Your portfolio ZIP is ready to download.')}
function portfolioHTML(){return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(data.name)} — Portfolio</title></head><body><header><b>${esc(data.name)}</b><nav><a href="#work">Work</a>　<a href="#about">About</a>　<a href="#contact">Contact</a></nav></header><section><small>${esc(data.role)} · ${esc(data.location)}</small><h1>Hi, I’m ${esc(data.name.split(' ')[0])}.<br>I build things for the web.</h1><p>${esc(data.bio)}</p></section><section id="work"><h2>A few things I’ve made.</h2><div class="projects">${data.projects.map(p=>`<article class="project"><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><p>${esc((p.stack||[]).join(' · '))}</p><a href="${esc(p.live||p.github||'#')}">View project ↗</a></article>`).join('')}</div></section><section id="about"><h2>About me</h2><p>${esc(data.degree)} · ${esc(data.school)} · ${esc(data.gradYear)}</p><p>${esc(data.skills.join(' · '))}</p></section><section id="contact"><h2>Say hello</h2><a href="mailto:${esc(data.email)}">${esc(data.email)}</a></section><footer>Designed with folio</footer></body></html>`}
function printCV(){const w=window.open('','_blank');if(!w){toast('Allow pop-ups to download your CV as PDF.');return}const body=`<header><h1>${esc(data.name)}</h1><div>${esc(data.role)} · ${esc(data.location)}</div><p>${esc(data.email)}${data.github?' · github.com/'+esc(data.github):''}</p></header><section><h2>Profile</h2><p>${esc(data.bio)}</p></section><section><h2>Education</h2><p><b>${esc(data.degree)}</b><br>${esc(data.school)}${data.gradYear?' · '+esc(data.gradYear):''}</p></section>${data.experience?`<section><h2>Experience</h2><p>${esc(data.experience).replace(/\n/g,'<br>')}</p></section>`:''}<section><h2>Selected projects</h2>${data.projects.map(p=>`<article><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><small>${esc((p.stack||[]).join(' · '))}</small></article>`).join('')}</section><section><h2>Skills</h2><p>${esc(data.skills.join(' · '))}</p></section>`;w.document.write(`<!doctype html><html><head><title>${esc(data.name)} — CV</title><meta name="viewport" content="width=device-width"><style>body{font:12px/1.6 Arial,sans-serif;color:#28332a;max-width:760px;margin:40px auto;padding:0 30px}h1{font-size:30px;margin:0}header{border-bottom:2px solid #6f895d;padding-bottom:12px}h2{font-size:14px;text-transform:uppercase;letter-spacing:1px;border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:21px}h3{font-size:13px;margin:8px 0 0}p{margin:6px 0;color:#515a52}small{color:#697467}article{margin:7px 0}@media print{body{margin:0 auto}}</style></head><body>${body}<script>window.onload=()=>window.print()</script></body></html>`);w.document.close()}
// Small uncompressed ZIP writer keeps static export dependency-free.
function zipStore(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;const crcTable=Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;return c>>>0});function crc(b){let c=0xffffffff;for(const x of b)c=crcTable[(c^x)&255]^(c>>>8);return(c^0xffffffff)>>>0}function u16(n){return[n&255,(n>>>8)&255]}function u32(n){return[n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]}for(const[name,content]of Object.entries(files)){const n=enc.encode(name),d=enc.encode(content),sum=crc(d),head=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(sum),...u32(d.length),...u32(d.length),...u16(n.length),...u16(0),...n]);parts.push(head,d);central.push(new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(sum),...u32(d.length),...u32(d.length),...u16(n.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...n]));offset+=head.length+d.length}const centralSize=central.reduce((a,x)=>a+x.length,0),end=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(central.length),...u16(central.length),...u32(centralSize),...u32(offset),...u16(0)]);return new Blob([...parts,...central,end],{type:'application/zip'})}
function share(){const url=apiEnabled?`${location.origin}/${encodeURIComponent(data.slug)}`:`${location.origin}${location.pathname}#/p/${data.slug}`;if(navigator.clipboard)navigator.clipboard.writeText(url).then(()=>toast('Portfolio link copied.')).catch(()=>toast(url));else toast(url)}
document.addEventListener('click',async e=>{const routeBtn=e.target.closest('[data-route]');if(routeBtn){route=routeBtn.dataset.route;if(location.hash.startsWith('#/p/'))location.hash='';else render();return}const template=e.target.closest('[data-template]');if(template){data.template=template.dataset.template;save();if(apiEnabled&&authenticated)api('/api/portfolio',{method:'PUT',body:JSON.stringify(data)}).catch(err=>toast(err.message));render();return}const color=e.target.closest('[data-color]');if(color){data.accent=color.dataset.color;save();if(apiEnabled&&authenticated)api('/api/portfolio',{method:'PUT',body:JSON.stringify(data)}).catch(err=>toast(err.message));render();return}const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='auth-toggle'){authMode=authMode==='signup'?'login':'signup';render()}else if(action==='logout'){api('/api/auth/logout',{method:'POST'}).finally(()=>{authenticated=false;route='dashboard';render()})}else if(action==='preview'){location.hash=`/p/${data.slug}`;render()}else if(action==='share')share();else if(action==='back'){location.hash='';route='dashboard';render()}else if(action==='add-project')projectForm(null);else if(action==='edit-project')projectForm(+a.dataset.index);else if(action==='delete-project'){if(confirm('Remove this project from your portfolio?')){const p=data.projects[+a.dataset.index];if(apiEnabled&&authenticated&&p.id)await api(`/api/projects/${p.id}`,{method:'DELETE'});data.projects.splice(+a.dataset.index,1);save();render();toast('Project removed.')}}else if(action==='github-import')githubModal();else if(action==='close-modal'){if(e.target===a||a.tagName==='BUTTON')a.closest('.modal-backdrop')?.remove()}else if(action==='print'){if(data.template.startsWith('cv-'))window.print();else printCV()}else if(action==='export')exportZip()});
document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='auth-form'){e.preventDefault();e.stopImmediatePropagation();const values=Object.fromEntries(new FormData(f));try{await api(`/api/auth/${authMode}`,{method:'POST',body:JSON.stringify(values)});authenticated=true;const result=await api('/api/portfolio');data={...initial,...result.portfolio};analyticsRemote=await api('/api/analytics');data.views=analyticsRemote.total;save();route='dashboard';serverError='';render();toast(authMode==='signup'?'Your account is ready.':'Welcome back.')}catch(err){toast(err.message)}return}if(f.id==='contact-form'&&route==='public'){e.preventDefault();e.stopImmediatePropagation();const values=Object.fromEntries(new FormData(f));try{await api(`/api/contact/${encodeURIComponent(publicSlug||data.slug)}`,{method:'POST',body:JSON.stringify(values)});document.querySelector('.modal-backdrop')?.remove();toast('Your message has been sent.')}catch(err){toast(err.message)}return}if(!apiEnabled||!authenticated)return;if(!['profile-form','project-form','github-form'].includes(f.id))return;if(f.id==='github-form'&&f.dataset.phase!=='select')return;e.preventDefault();e.stopImmediatePropagation();try{if(f.id==='profile-form'){const d=Object.fromEntries(new FormData(f));readProfileForm(d);const result=await api('/api/portfolio',{method:'PUT',body:JSON.stringify(data)});data={...data,...result.portfolio};save();render();toast('Profile saved.')}else if(f.id==='project-form'){const d=Object.fromEntries(new FormData(f));const item={...d,stack:d.stack.split(',').map(x=>x.trim()).filter(Boolean)};const i=f.dataset.index;const old=i===''?null:data.projects[+i];const result=old?.id?await api(`/api/projects/${old.id}`,{method:'PUT',body:JSON.stringify(item)}):await api('/api/projects',{method:'POST',body:JSON.stringify(item)});if(old)data.projects[+i]={...result.project};else data.projects.push(result.project);save();document.querySelector('.modal-backdrop')?.remove();render();toast('Project saved.')}else{const selected=[...f.querySelectorAll('input[name=repo]:checked')].map(c=>c.value);const repos=JSON.parse(f.dataset.repos||'[]');for(const name of selected){const repo=repos.find(x=>x.name===name);if(repo&&!data.projects.some(p=>p.title===repo.name)){const result=await api('/api/projects',{method:'POST',body:JSON.stringify({title:repo.name,description:repo.description||'An open source project.',stack:repo.language?[repo.language]:[],github:repo.html_url,live:repo.homepage||''})});data.projects.push(result.project)}}data.github=f.dataset.username;await api('/api/portfolio',{method:'PUT',body:JSON.stringify(data)});save();document.querySelector('.modal-backdrop')?.remove();route='projects';render();toast(`${selected.length} repos added to your projects.`)}}catch(err){toast(err.message)}},true);
document.addEventListener('input',e=>{if(e.target.name==='slug'){document.getElementById('slug-preview').textContent=e.target.value.replace(/[^a-z0-9-]/gi,'').toLowerCase()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-font]')){data.font=e.target.value;save();if(apiEnabled&&authenticated)api('/api/portfolio',{method:'PUT',body:JSON.stringify(data)}).catch(err=>toast(err.message));render()}if(e.target.matches('[data-color-input]')){data.accent=e.target.value;save();if(apiEnabled&&authenticated)api('/api/portfolio',{method:'PUT',body:JSON.stringify(data)}).catch(err=>toast(err.message));render()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='profile-form'){const d=Object.fromEntries(new FormData(f));readProfileForm(d);save();render();toast('Profile saved.')}if(f.id==='project-form'){const d=Object.fromEntries(new FormData(f));const p={...d,stack:d.stack.split(',').map(x=>x.trim()).filter(Boolean)};if(f.dataset.index==='')data.projects.push(p);else data.projects[+f.dataset.index]=p;save();document.querySelector('.modal-backdrop')?.remove();render();toast('Project saved.')}if(f.id==='github-form'){if(f.dataset.phase==='select'){const selected=[...f.querySelectorAll('input[name=repo]:checked')].map(c=>c.value);const rps=JSON.parse(f.dataset.repos||'[]');for(const name of selected){const x=rps.find(y=>y.name===name);if(x&&!data.projects.some(p=>p.title===x.name))data.projects.push({title:x.name,description:x.description||'An open source project.',stack:x.language?[x.language]:[],github:x.html_url,live:x.homepage||'',image:''})}data.github=f.dataset.username;save();document.querySelector('.modal-backdrop')?.remove();route='projects';render();toast(`${selected.length} repos added to your projects.`);return}const username=new FormData(f).get('username').trim();const button=document.getElementById('repo-submit');button.disabled=true;button.textContent='Looking up repositories…';const box=document.getElementById('repo-results');try{const r=await fetch(`https://api.github.com/users/${encodeURIComponent(username)}/repos?sort=updated&per_page=100`);if(!r.ok)throw new Error(r.status===404?'That username was not found.':'GitHub could not load repositories. Try again in a moment.');const repos=await r.json();box.style.display='block';box.innerHTML=repos.length?repos.map(x=>`<label class="repo-row"><input type="checkbox" name="repo" value="${esc(x.name)}"><span><strong>${esc(x.name)}</strong><small>${esc(x.description||'No description')} · ${esc(x.language||'Code')} · ${x.stargazers_count} stars</small></span></label>`).join(''):'<div class="empty">No public repositories found.</div>';button.textContent='Add selected projects';button.disabled=false;f.dataset.phase='select';f.dataset.username=username;f.dataset.repos=JSON.stringify(repos.map(x=>({name:x.name,description:x.description,html_url:x.html_url,language:x.language,homepage:x.homepage})));}catch(err){toast(err.message);button.disabled=false;button.textContent='Find repositories ↗'}}});
function profileScore(){return Math.min(100,Math.round(([data.name,data.role,data.bio,data.email,data.school,data.github,data.skills.length>=3,data.projects.length>=2].filter(Boolean).length/8)*100))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="back"]');if(b&&apiEnabled){e.preventDefault();e.stopImmediatePropagation();history.replaceState(null,'','/');location.hash='';route='dashboard';publicLoadError='';loadedPublicSlug='';render()}},true);
window.addEventListener('hashchange',()=>{publicLoadError='';route=location.hash.startsWith('#/p/')?'public':'dashboard';render()});if(apiEnabled)hydrate();else render();
